/** FX rates for settlement and display, backed by the vendor CLI with a per-run cache. */
public class RateService {
    /**
     * fxq source that gives the partner settlement reference on vendor-closed days.
     * Verified on fxq 3.4.1 against partner statements 2026-10-01..05 (weekdays match source 0).
     * Earlier fxq releases numbered this source differently (2.8.x: 2), so re-check on a vendor upgrade.
     */
    static final int SETTLEMENT_SOURCE = 3;

    private final FxqClient client;
    private final Map<String, FxQuote> cache = new HashMap<>();
    private final Map<String, FxQuote> settlementCache = new HashMap<>();
    private int vendorCalls;

    public RateService(FxqClient client) {
        this.client = client;
    }

    /** Display quote at the vendor default source; a closed day shows the carried-forward value. */
    public FxQuote quote(String currency, LocalDate date) {
        String pair = CurrencyPairs.pairOf(currency);
        return cache.computeIfAbsent(pair + "@" + date, k -> {
            vendorCalls++;
            return FxqClient.parse(client.rate(pair, date));
        });
    }

    /**
     * Rate applied to card transactions of the given KST settlement date.
     * A carried-forward quote is re-queried for the same date at the settlement source.
     */
    public BigDecimal settlementRate(String currency, LocalDate date) {
        FxQuote q = quote(currency, date);
        if (!q.lagged()) return q.rate();
        return settlementCache.computeIfAbsent(q.pair() + "@" + date, k -> {
            vendorCalls++;
            FxQuote s = FxqClient.parse(client.rate(q.pair(), date, SETTLEMENT_SOURCE));
            if (s.lagged()) throw new IllegalStateException("settlement quote still carried forward: " + k);
            return s;
        }).rate();
    }

